custom_defined_behaviors:
behaviors {
    /* @viewer: ⇪ | @badge: TD | @icon: caps | @tooltip: Tap Dance: 1x Caps Word • 2x Caps Lock */
    td_caps: td_caps {
        compatible = "zmk,behavior-tap-dance";
        label = "TD_CAPS";
        #binding-cells = <0>;
        tapping-term-ms = <250>;
        bindings = <&caps_word>, <&kp CAPS>;
    };
    /* @viewer: 🚀 | @badge: TD | @icon: rocket | @tooltip: Tap Dance: 1x Launcher (⌘Space) • 2x ⌘⇧Space */
    td_launcher: td_launcher {
        compatible = "zmk,behavior-tap-dance";
        label = "TD_LAUNCHER";
        #binding-cells = <0>;
        tapping-term-ms = <200>;
        bindings = <&kp LG(SPACE)>, <&kp LG(LS(SPACE))>;
    };
    /* @viewer: 📷 | @badge: TD | @icon: screenshot | @tooltip: Tap Dance: 1x Area (⌘⌥⇧4) • 2x Scrolling/Window (⌘⌥⇧2) • 3x Fullscreen (⌘⌥⇧3) */
    td_screenshot: td_screenshot {
        compatible = "zmk,behavior-tap-dance";
        label = "TD_SCREENSHOT";
        #binding-cells = <0>;
        tapping-term-ms = <250>;
        bindings = <&kp LG(LA(LS(N4)))>, <&kp LG(LA(LS(N2)))>, <&kp LG(LA(LS(N3)))>;
    };
    /* @viewer: 📋 | @badge: TD | @icon: clipboard | @tooltip: Tap Dance: 1x ⌘C (Copy) • 2x ⌘V (Paste) • 3x ⌘⌥V (Clippy) */
    td_copy_paste: td_copy_paste {
        compatible = "zmk,behavior-tap-dance";
        label = "TD_COPY_PASTE";
        #binding-cells = <0>;
        tapping-term-ms = <250>;
        bindings = <&kp LG(C)>, <&kp LG(V)>, <&kp LG(LA(V))>;
    };
    /* @viewer: 📋 | @badge: TD | @icon: clipboard | @tooltip: Tap Dance: 1x Ctrl+C (Copy) • 2x Ctrl+V (Paste) • 3x Win+V (Clipboard) */
    td_copy_paste_pc: td_copy_paste_pc {
        compatible = "zmk,behavior-tap-dance";
        label = "TD_COPY_PASTE_PC";
        #binding-cells = <0>;
        tapping-term-ms = <250>;
        bindings = <&kp LC(C)>, <&kp LC(V)>, <&kp LG(V)>;
    };
    /* @viewer: ⏯ | @badge: TD | @tooltip: Tap Dance: 1x Play/Pause • 2x Next Track • 3x Prev Track */
    td_media: td_media {
        compatible = "zmk,behavior-tap-dance";
        label = "TD_MEDIA";
        #binding-cells = <0>;
        tapping-term-ms = <250>;
        bindings = <&kp C_PP>, <&kp C_NEXT>, <&kp C_PREV>;
    };
    /* @viewer: 🌐 | @badge: TD | @icon: globe | @tooltip: Tap Dance: 1x History Back (⌘⌥H) • 2x History Forward (⌘⌥L) */
    td_browser: td_browser {
        compatible = "zmk,behavior-tap-dance";
        label = "TD_BROWSER";
        #binding-cells = <0>;
        tapping-term-ms = <250>;
        bindings = <&kp LG(LA(H))>, <&kp LG(LA(L))>;
    };
    /* @viewer: ◂🪟 | @badge: TD | @icon: window_prev | @tooltip: Tap Dance: 1x Prev Window (⌃⌘⇧U) • 2x Prev Workspace (⌃⌘,) */
    td_wm_prev: td_wm_prev {
        compatible = "zmk,behavior-tap-dance";
        label = "TD_WM_PREV";
        #binding-cells = <0>;
        tapping-term-ms = <250>;
        bindings = <&kp LC(LG(LS(U)))>, <&kp LC(LG(COMMA))>;
    };
    /* @viewer: 🪟▸ | @badge: TD | @icon: window_next | @tooltip: Tap Dance: 1x Next Window (⌃⌘u) • 2x Next Workspace (⌃⌘.) */
    td_wm_next: td_wm_next {
        compatible = "zmk,behavior-tap-dance";
        label = "TD_WM_NEXT";
        #binding-cells = <0>;
        tapping-term-ms = <250>;
        bindings = <&kp LC(LG(U))>, <&kp LC(LG(DOT))>;
    };
};
